// Build 14: filling the level 30-35 lands (the Wound, the Lightless March, the Frostcrown and the Throat of the World)
// to 60 quests each. Each land gets two new people with work to give, a few new things to find, and 49 smaller quests
// woven around the story that was already there.
import { S, X } from './core.js';
import { QUESTS } from './data.js';
import { TALK } from './dialogue.js';
import { ZSPEC } from './kit9.js';
import { giver } from './hi9.js';
import { finish35 } from './vh13.js';
import { side, props14, K, C, N, A, I, TK } from './l14.js';

const LA = r => ({ lantern: r }), CR = r => ({ crown: r }), CF = r => ({ candle: r }), TH = r => ({ thaw: r });
// add people to a land's towns, and things to its ground
const npc = (zone, town, row) => ZSPEC[zone].towns[town].npcs.push(row);
const things = (zone, rows) => { const sp = ZSPEC[zone], old = sp.after; sp.after = a => { old?.(a); props14(rows, a.rng); }; };

// ================= the Wound (30-32) =================
giver('tobin14', 'Tobin Ashgrove', 'Lampfall Camp · a Compact runner', 'archer1');
giver('gret14', 'Gret Ironhand', 'Ruinwatch · Legion smith', 'bulwark1');
npc('xw13', 0, ['giver', 'tobin14', 9, -3]); npc('xw13', 1, ['giver', 'gret14', 6, 6]);
Object.assign(TALK, {
  tobin14: { bio: 'Tobin runs messages for the Lantern Compact between camps that are mostly holes in the ground. He has outrun hounds, voidspawn and one very angry quartermaster.', greet: ["Message? No? Shame. I like running. It's the stopping I'm bad at.", "Lampfall to Ruinwatch in an hour. Don't believe the Legion if they say longer. They walk."], topics: [] },
  gret14: { bio: 'Gret mends the Iron Legion\'s armour at Ruinwatch. She lost two fingers to a forge and three to a voidspawn, and has opinions about which hurt more.', greet: ["Bring it here. Whatever it is, it's dented. Everything's dented here.", "The forge never goes out. Varga's orders. Mine too."], topics: [] },
});
X.inspectSay = Object.assign(X.inspectSay || {}, {
  woundcrack: ['A crack in the ground, still warm, where he came up. You drop a stone in. You never hear it land.', 'The crack breathes. In, out. You mark it on the map and back away.'],
  lostlantern: ['A Compact lantern, dropped in a hurry. You take it back.', 'A lantern on a post, cold. You light it.', 'Somebody\'s lantern, and their boots, and nothing else.'],
  choirmark13: ['An Upward Choir mark: a line going up. You scratch it out.', 'Chalk, fresh: "HE RISES". You rub it off.'],
  legioncache: ['A Legion supply cache, still sealed. Gret will be pleased.', 'Bolts, rivets, a spare helm. And a biscuit. You leave the biscuit.'],
});
things('xw13', [['woundcrack', 'A crack in the ground', 'opengrave', 0, 260, 5, 90], ['lostlantern', 'A dropped lantern', 'lampwreck14', -120, 330, 6, 100], ['choirmark13', 'A Choir mark', 'altar14', 300, 0, 5, 100], ['legioncache', 'A Legion cache', 'cache14', 260, 140, 4, 70]]);
const W = 'xw13', WILD = ['woundcrawler', 'cinderwing', 'hollowhound'];
const yw = [
  ...side(W, LA, 'xw1', [
    ['yw1', 'tobin14', 30, 'Runner\'s Road', 'woundedge', K(['hollowhound', 'woundcrawler'], 10, 'Clear 10 hounds and crawlers off the runner\'s road at the Wound\'s edge', 'woundedge', 200), "The road from Lampfall to the edge is mine. I run it twice a day. Lately things run it with me. Ten.", "Ten. I'll run it tomorrow with nothing behind me. It'll feel strange."],
    ['yw2', 'tobin14', 30, 'Dropped Lanterns', 'lampfall', I('lostlantern', 4, 'Recover 4 Compact lanterns dropped around Lampfall'), "People drop lanterns when they run. Everybody runs here. Four, and the Compact can light the camp road.", "Four. One of them was mine. Don't tell anyone."],
    ['yw3', 'oswin13', 30, 'Cinderwings', 'woundedge', K(['cinderwing'], 8, 'Shoot down 8 cinderwings over the Wound\'s edge', 'woundedge', 700), "Cinderwings nest in the hot rock round the Wound. They drop embers on the tents. Eight.", "Eight. The tents can stop smouldering now. They won't. But they can."],
    ['yw4', 'sela13', 30, 'Where He Came Up', 'woundedge', I('woundcrack', 3, 'Mark 3 of the cracks where Vhorun came up'), "I watched him come up. I didn't blink. I want the cracks mapped, every one. Three, for now.", "Three. Still warm. He's been gone a long way down and the ground still remembers him."],
    ['yw5', 'gret14', 30, 'Iron for the Forge', 'ironrim', C(['rockwraith'], 'Wraith-Iron', 6, 'Bring Gret 6 chunks of wraith-iron from the rock-wraiths'), "Rock-wraiths have iron in them. Good iron, if you can get it out. Six chunks.", "Lovely. Dense. The Legion's going to have the best dented armour in the world."],
    ['yw6', 'gret14', 30, 'Supply Caches', 'ironrim', I('legioncache', 3, 'Find 3 Legion supply caches buried near the Iron Rim'), "We buried supplies on the march in. The map's wrong. Of course it is. Find three.", "Three. Bolts and rivets. And a spare helm. Someone will be very pleased about the helm."],
    ['yw7', 'tobin14', 30, 'A Message for Ruinwatch', 'ironrim', A('ironrim', 'Run Tobin\'s message to the Iron Rim'), "My ankle's gone. Run this to the Rim for me. Don't read it. It's boring. It's about biscuits.", "Delivered? You ran it? Fast? How fast? Never mind. I'm faster."],
    ['yw8', 'varga13', 31, 'Upward Zealots', 'ironrim', K(['upzealot', 'upcaller'], 10, 'Break 10 of the Upward Choir camped on the Iron Rim', 'ironrim', 220), "The Upward Choir think Vhorun is going up to heaven and taking them with him. They're camped on my rim. Ten.", "Ten. They died singing. Hymns about going up. They went down."],
    ['yw9', 'sela13', 31, 'Hound Packs', 'lampfall', K(['hollowhound'], 10, 'Thin out 10 hollow hounds around Lampfall', 'lampfall', 240), "The hounds hunt in packs round the camp, at night. Ten fewer.", "Ten. I sat up and watched. You didn't blink either. I noticed."],
    ['yw10', 'gret14', 31, 'Cinder-Leather', 'woundedge', C(['cinderwing'], 'Cinder-Hide', 6, 'Bring Gret 6 cinder-hides for the forge aprons'), "Cinderwing hide doesn't burn. Good for aprons. Six. Mine's got holes you could put your arm through.", "New apron. Look at it. Doesn't even smoke. I'm going to wear it to bed."],
    ['yw11', 'oswin13', 31, 'Choir Marks', 'ironrim', I('choirmark13', 3, 'Scrub out 3 Upward Choir marks near the Rim'), "The Choir chalk their marks everywhere. A line going up. I'm sick of seeing it. Three.", "Three. They'll draw more. We'll scrub more. Such is war."],
    ['ywd1', 'tobin14', 30, 'The Morning Run', 'woundedge', K(['woundcrawler', 'hollowhound', 'cinderwing'], 8, 'Clear 8 things off the runner\'s road', 'woundedge', 220), "Morning run. Eight things to dodge. Or not dodge.", "Clear. Same tomorrow. Everything's the same tomorrow.", { daily: true }],
  ]),
  ...side(W, LA, 'xw3', [
    ['yw12', 'oswin13', 31, 'The Shattered Halls', 'halls', K(['hollowwarden', 'lightless'], 10, 'Clear 10 of the things around the Shattered Halls', 'halls', 200), "The Halls were a city. Vhorun came up under it. What's left is full of the people who lived there, a bit worse for it. Ten.", "Ten. Some of them were still wearing their house keys."],
    ['yw13', 'sela13', 31, 'Warden-Captain Brask', 'halls', N('wardenbrask13', 'Put down Warden-Captain Brask in the Shattered Halls'), "Brask kept the Halls' gate. He's still keeping it. He doesn't know there's nothing left to keep.", "Did he say anything? 'Halt'? He always said halt. He was a good man. He said halt to everyone."],
    ['yw14', 'gret14', 31, 'Warden Steel', 'halls', C(['hollowwarden'], 'Warden Plate', 6, 'Bring Gret 6 plates of old Halls warden steel'), "The Halls' wardens wore the best steel in the north. They're still wearing it. Six plates.", "Old steel. Folded a hundred times. They don't make it like this. They don't make anything like this. They're dead."],
    ['yw15', 'tobin14', 31, 'Gloomcasters', 'halls', K(['gloomcaster'], 8, 'Silence 8 gloomcasters near the Halls', 'halls', 220), "The gloomcasters throw dark like other people throw stones. One got me on the last run. I'm still seeing spots. Eight.", "Eight. Spots are fading. I can see your face. Huh."],
    ['yw16', 'varga13', 31, 'The Lamp-Eater', 'halls', N('lampeater13', 'Kill the Lamp-Eater in the Shattered Halls'), "Something in the Halls eats lamps. Lanterns, torches, candles, the lot. It ate my picket's watch-fire with the picket still sat by it.", "Dead? Good. I'll tell the picket's mother. She'll want to know it's dead."],
    ['yw17', 'sela13', 31, 'Keys to the Halls', 'halls', C(['lightless'], 'House Key', 6, 'Take back 6 house keys from the Lightless of the Halls'), "The Lightless in the Halls still carry their house keys. I want them. Somebody should keep them. For when the houses come back.", "Six keys. I'll hang them in the camp. Every one is a door somewhere."],
    ['yw18', 'oswin13', 31, 'Voidspawn', 'pit', K(['voidspawn'], 10, 'Kill 10 voidspawn near the Weeping Pit', 'pit', 240), "Voidspawn come up out of the Pit. Every night. They don't make any sound. That's the worst of it. Ten.", "Ten. Silent going down as well. I hate that."],
    ['yw19', 'tobin14', 31, 'Run to the Pit', 'pit', A('pit', 'Run out to the Weeping Pit and look at what\'s weeping'), "They call it the Weeping Pit. Something down there cries. I want to know what. I'm too fast to stop and look. You look.", "Lights? Crying? Down there? I'm not running that way again. I'm running the other way."],
    ['yw20', 'gret14', 31, 'The Forge Fire', 'ironrim', C(['cinderwing', 'rockwraith'], 'Ember-Core', 5, 'Bring Gret 5 ember-cores to keep the forge hot'), "The forge never goes out. To make sure, I need ember-cores. Five.", "Five. That's a week of forge. You're good for a week. You're good for more than that."],
    ['yw21', 'sela13', 32, 'Mournvoice', 'pit', N('mournvoice13', 'Silence Choir-Mother Ysolt at the Weeping Pit'), "The Choir-Mother leads the weeping. She weeps for Vhorun, because he's gone down. She wants him back up.", "Quiet. The Pit's quiet. I don't think I've heard it quiet before."],
    ['yw22', 'varga13', 32, 'Legion Lost', 'pit', C(['voidspawn', 'lightless'], 'Legion Tag', 5, 'Recover 5 Legion tags from the things near the Pit'), "Five of mine went to the Pit and didn't come back. Their tags will be out there. On something. Five.", "Five. I'll write the letters tonight. I write a lot of letters."],
    ['ywd2', 'varga13', 31, 'Rim Watch', 'ironrim', K(['upzealot', 'rockwraith', 'upcaller'], 8, 'Hold the Iron Rim against 8 attackers', 'ironrim', 220), "Rim watch. Eight. Every day.", "Held. Same tomorrow.", { daily: true }],
  ]),
  ...side(W, LA, 'xw5', [
    ['yw23', 'oswin13', 32, 'The Hollow Spine Road', 'spine', K(['voidspawn', 'lightless', 'gloomcaster'], 12, 'Clear 12 things on the road to the Hollow Spine', 'spine', 240), "The road to the Spine is the worst road in the Wound. Twelve, and the Compact can get supplies through.", "Through. The carts are moving. Slowly. Carefully. Like everything here."],
    ['yw24', 'sela13', 32, 'The Last Warden', 'lastwarden', A('lastwarden', 'Go to the Last Warden statue and keep watch for a while'), "There's a statue south, the Last Warden. I used to sit by it and watch. I can't any more. Sit by it for me. Tell me what you see.", "Lights? Going down? Yes. That's what I used to see. Every night. Him, going down, with everything he ate."],
    ['yw25', 'gret14', 32, 'A Better Helm', 'ironrim', C(['hollowwarden', 'rockwraith'], 'Good Steel', 6, 'Bring Gret 6 pieces of good steel for a hero\'s helm'), "You keep coming back with dents. Six pieces of good steel, and I'll make you a helm that doesn't.", "There. A helm. Don't get it dented. You'll get it dented. Bring it back when you do."],
    ['yw26', 'tobin14', 32, 'The Long Run', 'undergate', A('undergate', 'Run to the Undergate and back without stopping'), "The Undergate. Furthest anyone's run from Lampfall. I did it once. Prove you can. Don't stop. Not once.", "You didn't stop? Liar. You stopped once. I can tell. Your left boot's muddier. Still. Well run."],
    ['yw27', 'varga13', 32, 'Hold the Undergate Road', 'undergate', K(['voidspawn', 'lightless', 'gloomcaster', 'rockwraith'], 12, 'Clear 12 things on the road down to the Undergate', 'undergate', 240), "When we go down the Undergate, I want the road behind us clear. Twelve. That's what we do."],
    ['yw28', 'oswin13', 32, 'The Gnaw', 'ironrim', N('thegnaw13', 'Hunt down the Gnaw, somewhere east of the Rim'), "There's something east of the Rim that the Legion calls the Gnaw. It doesn't eat. It gnaws. For days. Kill it.", "The Gnaw's done gnawing. I'll tell Varga. She'll want to see it. She likes to see things."],
    ['yw29', 'sela13', 32, 'Mother Maw', 'halls', N('mothermaw13', 'Find Mother Maw, somewhere in the west'), "In the west there's a thing the hounds come out of. Mother Maw. I've watched her. She never sleeps. Neither do I."],
    ['yw30', 'gret14', 32, 'Shield Rims', 'ironrim', C(['upzealot', 'upcaller'], 'Choir Brass', 6, 'Take 6 pieces of Choir brass for shield rims'), "The Choir wear brass. Bells, mostly. Six bits. I'll put them on the shield rims. They'll ring when you hit things. Varga'll hate it.", "She hated it. She kept one. She rings it when nobody's looking."],
    ['yw31', 'tobin14', 32, 'Lanterns on the Road', 'lampfall', I('lostlantern', 2, 'Light the last 2 dropped lanterns on the camp road'), "Two more lanterns, out on the road. Light them. I want to run the whole road lit, just once.", "Lit. All the way. I ran it twice just to look. Don't tell Oswin."],
    ['yw32', 'oswin13', 32, 'The Weeping One', 'pit', N('weepingone13', 'Go down into the Weeping Pit and stop the Weeping One'), "At the bottom of the Pit is what everything's weeping for. It's weeping too. Make it stop.", "Stopped. All of it. The Pit's just a hole now. I like it better as a hole."],
    ['yw33', 'sela13', 32, 'Sela Blinks', 'lampfall', TK('Sit with Sela'), "I haven't blinked since he came up. Not once. I'm tired. Sit with me. If I blink, tell me what I missed.", "I blinked. You saw. Nothing happened. Nothing happened! I'm going to sleep for a week."],
    ['yw34', 'gret14', 32, 'Crack Sealing', 'woundedge', I('woundcrack', 2, 'Seal 2 more cracks round the Wound\'s edge with Gret\'s tar'), "The cracks breathe. I've made a tar that doesn't burn. Pour it in two. Let's see if the ground can hold its breath."],
    ['yw35', 'varga13', 32, 'Legion Caches', 'ironrim', I('legioncache', 1, 'Find the last of the Legion\'s caches near the Rim'), "One cache left. The one with the good wine in it. I didn't say that. Find it.", "Found it? Is the wine... Never mind. Bring it here. Tell nobody."],
    ['yw36', 'tobin14', 32, 'Fastest in the Compact', 'lampfall', TK('Race Tobin round the camp'), "Once round the camp. You and me. Loser carries the post for a week.", "You won. You WON? Best of three. Best of five. I'm carrying the post."],
    ['ywd3', 'oswin13', 32, 'Spine Patrol', 'spine', K(['voidspawn', 'lightless', 'gloomcaster'], 8, 'Patrol the Spine road and clear 8 things', 'spine', 240), "Spine patrol. Eight. Every day.", "Clear. Same tomorrow.", { daily: true }],
  ]),
];
// a few done lines the rows above leave out
const DONE_W = { yw27: "Clear behind us. The Legion's not sentimental. We like a clear road, though.", yw29: "She's dead? Mother Maw? I'm going to try sleeping. I've forgotten how. I'll learn.", yw34: "It's holding. The ground's holding its breath. Gret's tar works. Don't tell her. She'll be unbearable." };
for (const q of yw) if (DONE_W[q.id]) q.done = [DONE_W[q.id]];

// ================= the Lightless March (31-33) =================
giver('tom14', 'Old Wick-Tom', 'Candlehold · candle-seller', 'villager3');
giver('bram14', 'Bram the Bellman', 'Last Hearth · rings the hour', 'villager1');
npc('xm13', 0, ['giver', 'tom14', 9, -3]); npc('xm13', 1, ['giver', 'bram14', 6, 6]);
Object.assign(TALK, {
  tom14: { bio: 'Wick-Tom has sold candles in Candlehold for sixty years. Business was never better than the year the light went out. He is not proud of it. He is not ashamed of it either.', greet: ["Candles! Candles! One for the road, one for the dark, one for the dead.", "Beeswax. Tallow. Moth-wax, if you're brave. Don't light the moth-wax indoors."], topics: [] },
  bram14: { bio: 'Bram rings the bell at Last Hearth every hour, though nobody can tell the hours any more. He says if he stops, the dark will think it\'s won.', greet: ["Bong. That's the hour. Which hour? Doesn't matter. It's an hour.", "Every hour, on the hour. Forty years. Never missed one. Missed one. Never missed two."], topics: [] },
});
X.inspectSay = Object.assign(X.inspectSay || {}, {
  marchcandle: ['A candle left on a gatepost, burned to the stub. You light a new one.', 'A candle in a window of Avenmoor. Nobody home. You light it anyway.'],
  starlessroot: ['A Starless root, black and cold. It pulls light into it. You cut it.', 'You cut the root. It bleeds dark. Lovely.'],
  duskshrine: ['A shrine of the Long Dusk: a candle, upside down. You turn it the right way up.', 'The Long Dusk worship the dark that\'s coming. You put a lit candle on their shrine. It looks embarrassed.'],
  avenbell: ['One of Avenmoor\'s bells, fallen in the street. You ring it once. Something in the ruins answers.', 'A cracked bell. Bram will want to know about it.'],
});
things('xm13', [['marchcandle', 'A burned-out candle', 'lampwreck14', 250, 150, 6, 110], ['starlessroot', 'A Starless root', 'opengrave', -300, 140, 5, 70], ['duskshrine', 'A shrine of the Long Dusk', 'altar14', -80, 300, 5, 90], ['avenbell', 'A fallen bell', 'cache14', 0, -40, 4, 40]]);
const M = 'xm13';
const ym = [
  ...side(M, CF, 'xm1', [
    ['ym1', 'tom14', 31, 'Moth-Wax', 'candleroad', C(['candlemoth'], 'Moth-Wax', 6, 'Bring Wick-Tom 6 lumps of moth-wax from the gloom-moths'), "Gloom-moths make wax. Black wax. Burns blue. Six lumps, and I'll make you a candle that frightens ghosts.", "Here. Your candle. Don't light it indoors. Don't light it near Nell. She hates the smell."],
    ['ym2', 'tom14', 31, 'Candles on the Road', 'candleroad', I('marchcandle', 4, 'Relight 4 candles on the gateposts along the Candle Road'), "There's a candle on every gatepost from here to Last Hearth. Tradition. Most are out. Light four.", "Four. People can walk the road at night now. Well. At all."],
    ['ym3', 'aldous13', 31, 'Gloomstalkers', 'candleroad', K(['gloomstalker'], 10, 'Hunt 10 gloomstalkers along the Candle Road', 'candleroad', 700), "The gloomstalkers follow the candle-light into town. Ten.", "Ten. The road's yours. The road's everyone's. That was the point of it."],
    ['ym4', 'nell13', 31, 'Wick Thread', 'candleroad', C(['lightless'], 'Wick Thread', 6, 'Take back 6 lengths of wick thread from the Lightless'), "The Lightless steal wick. They don't use it. They just hate it. Six lengths.", "Six. Candlehold will burn bright another week. Every week counts."],
    ['ym5', 'bram14', 31, 'The Hour', 'lasthearth', TK('Ring the hour with Bram'), "It's nearly the hour. Want to ring it? Nobody's ever asked. Pull. Pull! Not that hard.", "BONG. That's the hour. You rang it. Now you know what it feels like to be useful. Ha."],
    ['ym6', 'mourne13', 31, 'Dusk Shrines', 'lasthearth', I('duskshrine', 3, 'Set the candles right on 3 shrines of the Long Dusk near Last Hearth'), "My old sisters built shrines all round Last Hearth. Candles upside down. Set them right. Three.", "Three. They'll see them and be furious. Good. I used to be furious. It passes."],
    ['ym7', 'bram14', 31, 'Sisters on the Road', 'lasthearth', K(['dusksister'], 8, 'Turn back 8 Sisters of the Long Dusk around Last Hearth', 'lasthearth', 240), "The Sisters come to Last Hearth to ring my bell backwards. Eight. My bell, my way.", "Eight. Bell's safe. The hour's safe. Hours are important. Somebody has to say so."],
    ['ym8', 'aldous13', 31, 'Lantern Oil', 'candlehold', C(['gloomstalker', 'candlemoth'], 'Rendered Fat', 6, 'Bring Lord-Warden Aldous 6 measures of rendered fat for lamp-oil'), "Candlehold burns through oil like a drunk through ale. Six measures of fat. Don't ask from what.", "Six. The walls stay lit another night. I'm grateful. I'm also tired. Mostly tired."],
    ['ym9', 'nell13', 31, 'Nell\'s Lanterns', 'candleroad', A('candleroad', 'Hang Nell\'s new lanterns along the Candle Road'), "I've made lanterns. Proper ones, glass all round, so the wind can't get them. Hang them on the road. Start at the gate.", "Hung? All of them? I'm going to walk down there and look. I'm going to look all night."],
    ['ymd1', 'tom14', 31, 'Candle Rounds', 'candleroad', K(['gloomstalker', 'candlemoth', 'lightless'], 8, 'Walk Tom\'s candle rounds and clear 8 things', 'candleroad', 220), "Candle rounds. Eight things to shoo off.", "Done. Same tomorrow.", { daily: true }],
  ]),
  ...side(M, CF, 'xm3', [
    ['ym10', 'aldous13', 32, 'Fallen Avenmoor', 'avenmoor', K(['lightlessknight', 'lightless'], 10, 'Clear 10 of the Lightless in Fallen Avenmoor', 'avenmoor', 200), "Avenmoor was my city. Was. The Lightless walk its streets now in my knights' armour. Ten.", "Ten. Some of them I knew by their walk. I'll stop saying that. I won't."],
    ['ym11', 'bram14', 32, 'Avenmoor\'s Bells', 'avenmoor', I('avenbell', 3, 'Find 3 of Avenmoor\'s fallen bells'), "Avenmoor had twelve bells. I trained on them. Find three. Tell me if any can still ring.", "One rings? One. I'll take one. One's enough to start again."],
    ['ym12', 'aldous13', 32, 'Sheriff Gaunt', 'avenmoor', N('sheriffgaunt13', 'Stop Sheriff Gaunt in Fallen Avenmoor'), "Gaunt was Avenmoor's sheriff. He still arrests people. For being alive. Stop him.", "Gaunt's done. He was a hard man. He'd want to be stopped hard."],
    ['ym13', 'mourne13', 32, 'The Bell-Ringer', 'avenmoor', N('bellringer13', 'Silence the Bell-Ringer in Avenmoor'), "Something rings Avenmoor's last bell all night. The wrong way. It calls the Sisters. It called me, once. Silence it.", [["bram14", "Silenced? The Bell-Ringer? Good. That was a terrible ringer. No rhythm. No soul."]]],
    ['ym14', 'nell13', 32, 'Knight\'s Wax', 'avenmoor', C(['lightlessknight'], 'Seal-Wax', 5, 'Take 5 seals of wax from the Lightless knights'), "Avenmoor's knights sealed their oaths in wax. Red wax. They still carry them. Five. I'll melt them into candles and light them for the knights."],
    ['ym15', 'tom14', 32, 'Starless Roots', 'wood', I('starlessroot', 3, 'Cut 3 of the Starless roots that drink the light'), "The Starless Wood has roots that drink light. They're spreading toward the road. Cut three.", "Three. Lovely. My candles burn longer already. I swear it."],
    ['ym16', 'aldous13', 32, 'Starless Treants', 'wood', K(['shadowtreant'], 8, 'Fell 8 Starless treants in the Wood', 'wood', 200), "The trees in the Starless Wood walk. And eat. And walk some more. Eight.", "Eight. Firewood for a month. Dark firewood. Burns dim. Still burns."],
    ['ym17', 'mourne13', 32, 'Old Gloam', 'wood', N('oldgloam13', 'Bring down Old Gloam in the Starless Wood'), "Old Gloam is the oldest tree in the Wood. The Long Dusk prayed to it. I prayed to it. It never answered. Maybe it will now.", "Did it say anything? A creak? That's an answer. I'll take it."],
    ['ym18', 'bram14', 32, 'Gloomcasters', 'avenmoor', K(['gloomcaster'], 8, 'Kill 8 gloomcasters in Avenmoor\'s streets', 'avenmoor', 220), "Gloomcasters smother the street lamps. Eight. I want to see Avenmoor's streets lit, even once."],
    ['ym19', 'nell13', 32, 'Treant Sap', 'wood', C(['shadowtreant'], 'Dark Sap', 5, 'Bring Nell 5 jars of dark sap from the Starless treants'), "Starless sap burns slow. Slower than wax. Five jars, and I can make candles that last all night.", "All night. A candle that lasts all night. My grandmother would have cried. I might cry."],
    ['ym20', 'tom14', 32, 'Widow Candle', 'candleroad', N('widowcandle13', 'Find the Widow Candle, somewhere north of the road'), "There's a thing up north that the townsfolk call the Widow Candle. Burns on its own. Lures folk off the road. Put it out.", "Out? Shame. Lovely light. Terrible manners."],
    ['ymd2', 'aldous13', 32, 'Avenmoor Patrol', 'avenmoor', K(['lightlessknight', 'lightless', 'gloomcaster'], 8, 'Patrol Avenmoor and clear 8 of the Lightless', 'avenmoor', 220), "Avenmoor patrol. Eight. Every day until it's ours.", "Clear. Same tomorrow.", { daily: true }],
  ]),
  ...side(M, CF, 'xm5', [
    ['ym21', 'mourne13', 33, 'The Court Road', 'court', K(['lightlessknight', 'dusksister', 'gloomcaster'], 12, 'Clear 12 things on the road to the Court of Shadows', 'court', 240), "The Court of Shadows is where the Long Dusk plan. The road there is full of them. Twelve.", "Twelve. The road's open. The Court knows we're coming. It always knows."],
    ['ym22', 'aldous13', 33, 'Lord Mayor Aldric', 'avenmoor', N('lordmayor13', 'Lay Lord Mayor Aldric Vane to rest in Avenmoor'), "Aldric was my friend. My mayor. He's still in the town hall, giving speeches. To nobody. Lay him down.", "His last speech. What was it about? ...Candles. Of course it was."],
    ['ym23', 'nell13', 33, 'The Hollow Stag', 'wood', N('hollowstag13', 'Hunt the Hollow Stag in the Starless Wood'), "There's a stag in the Wood with nothing inside it. Hollow. You can see the dark through its ribs. Hunt it. Bring me the antlers. For a candle-tree.", "A candle-tree from the Hollow Stag. It's going in the window. Everyone will see it."],
    ['ym24', 'bram14', 33, 'A Bell for Last Hearth', 'avenmoor', I('avenbell', 1, 'Find the last of Avenmoor\'s bells, the one that still rings'), "The bell you found that still rings. I want it. Here. At Last Hearth. Ring it once where it lies, so I know which.", "I heard it. From here. All the way from Avenmoor. That's my bell now."],
    ['ym25', 'tom14', 33, 'Gate Lights', 'gate', K(['lightlessknight', 'voidspawn', 'dusksister'], 12, 'Clear 12 things around the old gate in the south', 'gate', 240), "The south gate used to have a candle on each post. Nobody's been near it in a year. Twelve, and I'll go down there with a basket."],
    ['ym26', 'mourne13', 33, 'My Old Sisters', 'court', C(['dusksister'], 'Dusk Veil', 6, 'Take 6 dusk veils from the Sisters of the Long Dusk'), "I wore a veil, once. Black, with a candle stitched upside down. Bring me six. I'll burn them. I want to watch."],
    ['ym27', 'aldous13', 33, 'The Starless Witch', 'wood', N('starlesswitch13', 'Stop the Starless Witch in the heart of the Wood'), "At the heart of the Wood there's a witch who teaches the trees to walk. Stop her. I want my woods back. I want my wood back. For candles."],
    ['ym28', 'nell13', 33, 'Candles for the Cathedral', 'cathedral', A('cathedral', 'Carry a box of Nell\'s candles to the steps of the Lightless Cathedral'), "When we go into the Cathedral, I want candles there already. Waiting. Leave a box on the steps. Don't go in. Not yet.", "Left them? On the steps? The Cathedral's got candles again. First in a year. They'll hate that. I love that."],
    ['ym29', 'bram14', 33, 'The Lost Hour', 'lasthearth', TK('Ask Bram about the hour he missed'), "You want to know about the hour I missed. Everyone does. Sit.", "My daughter was born. I missed the hour. I'd miss it again. Don't tell anyone. They'd think I'm soft."],
    ['ym30', 'tom14', 33, 'Sixty Years of Candles', 'candlehold', TK('Hear Wick-Tom\'s story'), "Sixty years. I've sold a candle to every family in the March. I'd like to tell somebody what that's like. You'll do.", "And they all came back. Every one. For another candle. That's the trade. That's the whole trade."],
    ['ym31', 'mourne13', 33, 'Dusk Shrines Again', 'lasthearth', I('duskshrine', 2, 'Turn 2 more Long Dusk shrines right way up'), "Two more shrines. Upside down again. They come back every night. So do I."],
    ['ym32', 'aldous13', 33, 'Knights of Avenmoor', 'court', K(['lightlessknight'], 10, 'Lay 10 more Lightless knights of Avenmoor to rest near the Court', 'court', 700), "My knights. Ten more. Then they'll all be resting. I'll know the number. I'll always know the number."],
    ['ym33', 'nell13', 33, 'Candlewright\'s Mark', 'candleroad', I('marchcandle', 2, 'Light the last 2 candles on the Candle Road with Nell\'s mark'), "Two candles left on the road. Light them with these. They've got my mark on them. Every candle on the road will be mine."],
    ['ymd3', 'mourne13', 33, 'Court Watch', 'court', K(['dusksister', 'gloomcaster', 'lightlessknight'], 8, 'Watch the Court road and clear 8 things', 'court', 240), "Eight. Every day. The Court never rests.", "Clear. Same tomorrow.", { daily: true }],
  ]),
];
const DONE_M = { ym14: "Five oaths. I'll light them tonight. I'll say the knights' names. I learned them from the seals.", ym18: "Lit. Avenmoor's streets, lit. I rang the bell for it. Did you hear? I rang it twice.", ym25: "Twelve. I'll go down there. With a basket. A big basket.", ym26: "Gone. Burned. The smoke was black. Then it was grey. Then it was nothing. That's how it goes.", ym27: "She's gone? The trees stopped walking? Firewood. Glorious firewood.", ym31: "Right way up. Every candle. They'll be back. So will I. That's how it works.", ym32: "Ten. All of them, then. Resting. I'll write the number in the hall. And all the names.", ym33: "Mine. All of them. A road of candles, from Candlehold to Last Hearth, with my mark on every one." };
for (const q of ym) if (DONE_M[q.id]) q.done = [DONE_M[q.id]];

// ================= the Frostcrown (32-34) =================
giver('inga14', 'Inga Frostbraid', 'Thawhold · the Thawborn', 'bladewarden1');
giver('jory14', 'Jory of the Chains', 'Hearth\'s End · once a prisoner', 'villager1');
npc('xf13', 0, ['giver', 'inga14', 9, -3]); npc('xf13', 1, ['giver', 'jory14', 6, 6]);
Object.assign(TALK, {
  inga14: { bio: 'Inga was born the day the Frostcrown first thawed, which makes her the oldest of the Thawborn and the loudest. She has never been cold. She thinks this is a moral achievement.', greet: ["Cold? You're cold? It's barely snowing.", "The Thawborn take back the Frostcrown one foot at a time. My feet. Mostly my feet."], topics: [] },
  jory14: { bio: 'Jory spent eleven years in the Tithe-Cells. He still wears the chains, unlocked, because he says he got used to the weight and the ground feels like it might float off without them.', greet: ["The chains? Don't mind them. They're on my side now.", "Eleven years. I counted every day on the wall. Then I ran out of wall."], topics: [] },
});
X.inspectSay = Object.assign(X.inspectSay || {}, {
  tithestone: ['A tithe-stone: names of everyone who paid, cut in the ice. You chip them out. They paid enough.', 'A tithe-stone. Some of the names are children. You chip those out first.'],
  frozenwagon: ['A tithe-wagon, frozen into the road. Inside: furs, food, a doll. You take what can be carried.', 'An empty wagon, iced over. Someone scratched "SORRY" into the seat.'],
  cellmark: ['A tally on the ice-wall of the cells: hundreds of marks. You add one, for whoever made them.', 'A name, cut in the ice, over and over. You read it out loud.'],
  thawstone: ['A Thawborn marker-stone, knocked over. You set it up. The snow around it starts to melt.', 'You set the marker upright. It\'s warm, very slightly. That\'s the point.'],
});
things('xf13', [['tithestone', 'A tithe-stone', 'carving14', -300, 60, 5, 90], ['frozenwagon', 'A frozen tithe-wagon', 'cache14', -200, 140, 5, 120], ['cellmark', 'A tally on the ice', 'carving14', -200, -240, 4, 60], ['thawstone', 'A Thawborn marker', 'lampwreck14', 60, 260, 6, 120]]);
const F = 'xf13';
const yf = [
  ...side(F, TH, 'xf1', [
    ['yf1', 'inga14', 32, 'One Foot at a Time', 'thaw', I('thawstone', 4, 'Set upright 4 Thawborn marker-stones in the thaw'), "The Thawborn mark the ground we take back. Stones. Something keeps knocking them over. Set four upright.", "Four. That's four feet of the Frostcrown that's ours. My feet. Ha."],
    ['yf2', 'inga14', 32, 'Snowstalkers', 'thaw', K(['snowstalker'], 10, 'Hunt 10 snowstalkers in the thaw', 'thaw', 700), "Snowstalkers follow the warm. We're the warm. Ten.", "Ten. Warm blood on the snow. The snow didn't like it. I did."],
    ['yf3', 'astrid13', 32, 'Ice-Wisps', 'thaw', K(['icewisp'], 8, 'Snuff 8 ice-wisps that freeze the thaw again', 'thaw', 220), "The wisps undo our thaw. They float over the soft ground and freeze it solid again. Eight.", "Eight. The ground's soft. I stood on it barefoot. Don't tell Inga, she'll say she does it all the time."],
    ['yf4', 'jory14', 32, 'Chain Links', 'hearthsend', C(['frostwight'], 'Iron Link', 6, 'Take 6 links of tithe-chain from the frost-wights'), "The frost-wights wear chains. Our chains. From the cells. Six links. I'm making something. I'll tell you when it's done.", "Six. It's a bell. A bell made of chain. It's going to ring for every one of us who didn't get out."],
    ['yf5', 'hallvard13', 32, 'Run Hearth\'s End', 'hearthsend', K(['glacialhulk', 'snowstalker'], 10, 'Clear 10 things off the paths round Hearth\'s End', 'hearthsend', 240), "Hearth's End is the last fire before the ice. Ten, so the runners can come and go.", "Ten. The runners are out. I can hear them laughing. Runners laugh. Prisoners don't. We're runners now."],
    ['yf6', 'jory14', 32, 'Eleven Years', 'hearthsend', TK('Hear Jory\'s story'), "You want to know about the cells. Everyone does, then they don't. Sit. I'll keep it short.", "Eleven years. Then you came, and the door opened, and I didn't know how to walk out of it. I'm still learning."],
    ['yf7', 'inga14', 32, 'Hulk Hide', 'hearthsend', C(['glacialhulk'], 'Hulk Hide', 5, 'Bring Inga 5 glacial-hulk hides'), "Hulk hide is the warmest thing in the north. I don't need it. The children do. Five.", "Five. Five warm children. Don't tell them it's from a hulk. They'll want to see one."],
    ['yf8', 'astrid13', 32, 'Fur for Thawhold', 'thaw', C(['snowstalker'], 'Stalker Pelt', 6, 'Bring Astrid 6 snowstalker pelts'), "Thawhold's blankets are thin. Six pelts.", "Six. Thawhold sleeps warm tonight. First time since we took it."],
    ['yf9', 'jory14', 32, 'The Chain-Hound', 'titheroad', N('chainhound13', 'Kill the Chain-Hound on the Tithe Road'), "There's a hound on the Tithe Road. Chained. To nothing. It drags the chain behind it and it never stops. It caught me twice. Kill it.", "Dead. Good. I'm going to take its chain. I'm going to put it on the bell."],
    ['yfd1', 'inga14', 32, 'Keep the Thaw', 'thaw', K(['snowstalker', 'icewisp', 'frostwight'], 8, 'Keep 8 things off the thaw', 'thaw', 220), "Eight a day. The thaw needs keeping.", "Kept. Same tomorrow.", { daily: true }],
  ]),
  ...side(F, TH, 'xf3', [
    ['yf10', 'astrid13', 33, 'The Tithe Road', 'titheroad', K(['tithetaker', 'rimeguard'], 10, 'Break 10 of the King\'s tithe-takers on the Tithe Road', 'titheroad', 220), "The Tithe Road is where they took everything from us. Food, furs, children. The tithe-takers still walk it. Ten.", "Ten. They didn't take anything today. First day in a hundred years."],
    ['yf11', 'jory14', 33, 'Tithe-Stones', 'titheroad', I('tithestone', 4, 'Chip the names out of 4 tithe-stones on the Tithe Road'), "Every family that paid the tithe had its name cut in a stone. Mine's on one. Chip them out. Four. They paid enough.", "Four. Mine was on the third one. I watched you chip it. I didn't think I'd cry. I didn't. Nearly."],
    ['yf12', 'inga14', 33, 'Frozen Wagons', 'titheroad', I('frozenwagon', 4, 'Search 4 frozen tithe-wagons along the road'), "The tithe-wagons froze on the road when the King fell. Full. Search four. Bring back what's ours.", "Food, furs. A doll. Somebody's doll. I'm going to find out whose. I'm going to give it back."],
    ['yf13', 'hallvard13', 33, 'Wagon-Master Gile', 'titheroad', N('wagonmaster13', 'Stop Wagon-Master Gile on the Tithe Road'), "Gile drove the wagons. He's still driving. Nowhere. He drove me to the cells, once. Stop him."],
    ['yf14', 'astrid13', 33, 'Rimeguard Shields', 'titheroad', C(['rimeguard'], 'Rime-Shield', 5, 'Take 5 shields from the Rimeguard of the Frostcrown'), "The Rimeguard carry shields of ice that don't melt. Five. The Thawborn will carry them now. Ice that's ours.", "Five. Look at them shine. Ice that's on our side. I never thought I'd say that."],
    ['yf15', 'jory14', 33, 'The Glass Glacier', 'glacier', K(['frostwight', 'icewisp', 'glacialhulk'], 12, 'Clear 12 things on the Glass Glacier', 'glacier', 200), "The Glass Glacier. You can see the dead inside it. Some of them are moving. Twelve."],
    ['yf16', 'inga14', 33, 'The Glass Maiden', 'glacier', N('glassmaiden13', 'Shatter the Glass Maiden on the Glacier'), "There's a woman made of glass on the Glacier. Walks the ice. Sings. Everyone who listens freezes. Shatter her.", "Shattered? Good. I listened, once. Just a bit. I was cold for a week. Me. Cold."],
    ['yf17', 'hallvard13', 33, 'Runners\' Cache', 'glacier', C(['icewisp', 'frostwight'], 'Runner\'s Pack', 5, 'Recover 5 runners\' packs lost on the Glacier'), "Five runners went over the Glacier and didn't come back. Their packs will be out there. With messages. Five."],
    ['yf18', 'astrid13', 33, 'The Glacier Wyrm', 'glacier', N('glacierwyrm13', 'Kill the Glacier Wyrm under the Glass Glacier'), "There's a wyrm under the Glacier. You can see it through the ice, swimming. Kill it before it comes up."],
    ['yf19', 'jory14', 33, 'Old Fang', 'hearthsend', N('theoldfang13', 'Hunt down Old Fang, somewhere east of Hearth\'s End'), "Old Fang. A wolf as big as a cart. It guarded the cells' east gate. It knows my smell. Kill it before it finds me."],
    ['yfd2', 'astrid13', 33, 'Tithe Road Watch', 'titheroad', K(['tithetaker', 'rimeguard', 'snowstalker'], 8, 'Watch the Tithe Road and clear 8 things', 'titheroad', 240), "Eight. Every day. The road's ours now.", "Ours. Same tomorrow.", { daily: true }],
  ]),
  ...side(F, TH, 'xf5', [
    ['yf20', 'jory14', 34, 'The Cells', 'cells', I('cellmark', 3, 'Find 3 of the tallies scratched on the walls outside the Tithe-Cells'), "Outside the cells, on the ice wall, people scratched tallies. Days. Find three. Read me the numbers.", "Four thousand. Two thousand. Eleven years. That one's mine. You found mine."],
    ['yf21', 'hallvard13', 34, 'Turnkeys', 'cells', K(['rimeguard', 'frostwight', 'tithetaker'], 12, 'Clear 12 of the guards around the Tithe-Cells', 'cells', 220), "The cells are empty. The guards don't know. They guard them anyway. Twelve."],
    ['yf22', 'inga14', 34, 'The Rime-Hag', 'glacier', N('rimehag13', 'Find the Rime-Hag, somewhere in the middle of the Frostcrown'), "There's a hag who walks the middle of the Frostcrown, freezing everything she passes. She froze my brother. He's thawed now. He's still angry. So am I."],
    ['yf23', 'astrid13', 34, 'The Tithe-Master', 'titheroad', N('tithemaster13', 'Bring down the Tithe-Master'), "The Tithe-Master counted everything we owed. Counted it in children, some years. He's still counting. Stop him."],
    ['yf24', 'jory14', 34, 'The Chain Bell', 'hearthsend', TK('Help Jory hang the chain bell'), "It's done. The bell. Made of chain. Help me hang it. It's heavier than it looks. Like chains."],
    ['yf25', 'hallvard13', 34, 'The Petitioners', 'petitioners', K(['frostwight', 'rimeguard', 'glacialhulk'], 12, 'Clear 12 things around the frozen petitioners', 'petitioners', 240), "Out east there's a line of people frozen in the snow. Petitioners. Waiting to see the King. They've been waiting a hundred years. Clear the things around them. Twelve."],
    ['yf26', 'inga14', 34, 'Thaw the Petitioners', 'petitioners', A('petitioners', 'Go to the frozen petitioners with a Thawborn torch'), "Take this torch to the petitioners. Hold it close. Not to thaw them. Just so they're warm for a bit. A hundred years is long enough to be cold."],
    ['yf27', 'astrid13', 34, 'The Heart of Winter', 'glacier', N('heartofwinter13', 'Break the Heart of Winter at the centre of the Glacier'), "At the centre of the Glacier is the cold itself. A heart. It beats once a day and the whole north freezes again. Break it."],
    ['yf28', 'jory14', 34, 'Tally Done', 'cells', I('cellmark', 1, 'Scratch the last tally mark on the cell wall: the day everyone got out'), "One more mark. On the wall. The day we got out. You make it. I can't hold the knife steady."],
    ['yf29', 'inga14', 34, 'The Throne Road', 'throne', K(['rimeguard', 'frostwight'], 12, 'Clear 12 Rimeguard on the road to the White Throne', 'throne', 240), "The road to the White Throne. The Rimeguard still hold it. Twelve. The Thawborn are going up there one day. I'd like the road clear."],
    ['yf30', 'hallvard13', 34, 'Running Days', 'hearthsend', TK('Hear Hallvard\'s plan'), "I've got a plan. Runners. Real ones. A post, from Thawhold to the Wound, so no village in the north is ever cut off again. Listen."],
    ['yf31', 'jory14', 34, 'Taking Off the Chains', 'hearthsend', TK('Help Jory take off his chains'), "I think. I think it's time. Will you help me take them off? I can't do the clasp. I've never been able to do the clasp."],
    ['yf32', 'astrid13', 34, 'Thawborn Markers', 'thaw', I('thawstone', 2, 'Set the last 2 Thawborn marker-stones'), "Two more markers. The last two I have. Set them. Then the thaw goes from here to the Glacier."],
    ['yf33', 'inga14', 34, 'Inga Is Cold', 'thawhold', TK('Talk to Inga'), "I'm cold. I've never been cold. I'm cold. Is this what it's like? How do you bear it?"],
    ['yfd3', 'hallvard13', 34, 'Run the Post', 'petitioners', K(['frostwight', 'glacialhulk', 'icewisp'], 8, 'Run the post road and clear 8 things', 'petitioners', 240), "Run the post. Eight things in the way. Every day.", "Run. Same tomorrow.", { daily: true }],
  ]),
];
const DONE_F = { yf13: "Stopped. He was a small man. I'd always thought he was enormous. Funny, what cells do.", yf15: "Twelve. You can see them in the ice still. Not moving now. That's better. That's a lot better.", yf17: "Five packs. Five messages. One of them's a love letter. I'm going to deliver it. A hundred years late is still delivered.", yf18: "Dead. Under the ice. You can still see it. Children will come to look at it for years. Good.", yf19: "Old Fang. Dead. I'm going to sleep with the door open tonight. Just to see what it's like.", yf21: "Twelve. Nobody's guarding the cells now. They're just empty. Empty's good.", yf22: "Gone? The Hag? My brother will want to see. He'll want to see the body. He'll want to kick it.", yf23: "Done counting. Finally. Nobody in the north owes anything to anyone now. Not one tithe.", yf24: [["jory14", "There. Ring it. Go on."], ["jory14", "Hear that? That's everybody. Every one of us. I'm going to ring it every morning."]], yf25: "Twelve. They're safe. Still frozen. Still waiting. But safe.", yf26: "Warm for a bit. Did any of them move? No. Of course not. Inga says one of them smiled. Inga sees things.", yf27: "Broken. Feel that? The wind's warm. The wind's never warm. The whole north is going to thaw.", yf28: "There. The last mark. The day we got out. Now the tally's finished.", yf29: "Clear. All the way to the Throne. One day. Not today. One day.", yf30: "Good plan? Good plan. I'll need runners. Fast ones. I'll need you, sometimes. Don't run too fast.", yf31: [["jory14", "Off. They're off."], ["jory14", "The ground's still there. It's not floating off. I'm not floating off. I'm going to go for a walk. A long one."]], yf32: "Set. From here to the Glacier, ours. A thaw you can walk on.", yf33: "Warm? A fire. Yes. I'll sit by the fire. Is that what you do? I'll try it. Don't tell anyone." };
for (const q of yf) if (DONE_F[q.id]) q.done = [].concat(typeof DONE_F[q.id] === 'string' ? [DONE_F[q.id]] : DONE_F[q.id]);

// ================= the Throat of the World (34-35) =================
giver('nan14', 'Nan Emberlee', 'The Last Light · keeps the camp fed', 'villager2');
giver('cobb14', 'Brother Cobb', 'Ember Watch · keeps the ember', 'cleric1');
npc('xt13', 0, ['giver', 'nan14', 9, -3]); npc('xt13', 1, ['giver', 'cobb14', 6, 6]);
Object.assign(TALK, {
  nan14: { bio: 'Nan cooks for the Last Light. Four hundred people, one pot. She has fed armies before. She says this one eats more and complains less.', greet: ["Eat. You've not eaten. I can tell. Eat.", "There's stew. There's always stew. Don't ask what's in it. It's stew."], topics: [] },
  cobb14: { bio: 'Brother Cobb carries the ember for Ember Watch when Iven sleeps. He has never let it go out. He has burned his hands eleven times. He keeps count.', greet: ["The ember's fine. The ember's always fine. My hands are less fine.", "Eleven burns. Twelve if you count the time I sneezed."], topics: [] },
});
X.inspectSay = Object.assign(X.inspectSay || {}, {
  biteMark: ['A bite in the ground the size of a house. Fresh. You mark it.', 'The bite goes down further than you can see. You can hear chewing.'],
  pilgrimpack: ['A pilgrim\'s pack, dropped on the way to the Throat. A prayer-book. A comb. A letter home, never sent. You take the letter.', 'A pack. Inside, bread, gone hard. And a child\'s drawing of a big smiling mouth.'],
  starlens: ['A Starwright lens, dropped. It shows the sky full of lights going home.', 'A lens. Through it, Vhorun looks very small. A child, curled up.'],
  embershrine: ['An ember-shrine on the road. Cold. You light it from Cobb\'s taper.', 'You light the shrine. The ember takes. It looks like a little sun.'],
});
things('xt13', [['biteMark', 'A bite in the ground', 'opengrave', -300, 100, 5, 110], ['pilgrimpack', 'A pilgrim\'s pack', 'cache14', 60, 60, 6, 110], ['starlens', 'A Starwright lens', 'coil14', 60, -120, 4, 70], ['embershrine', 'An ember-shrine', 'lampwreck14', 200, 160, 5, 110]]);
const T = 'xt13';
const yt = [
  ...side(T, LA, 'xt1', [
    ['yt1', 'nan14', 34, 'Stew', 'outskirts', C(['gnawling'], 'Gnawling Haunch', 6, 'Bring Nan 6 gnawling haunches for the pot'), "Stew needs meat. Gnawlings are meat. Don't make that face. Six haunches.", "Six. Four hundred people eat tonight. Don't ask what's in it. You know what's in it."],
    ['yt2', 'cobb14', 34, 'Ember-Shrines', 'emberwatch', I('embershrine', 4, 'Relight 4 ember-shrines on the road to Ember Watch'), "There are ember-shrines on the road. Little fires for the pilgrims. Light four from my taper. Don't drop it. Don't burn your hands. I've burned enough for both of us.", "Four. The road's got little suns on it. Pilgrims will see them. Some of them will stop."],
    ['yt3', 'mira13', 34, 'Hosthounds', 'outskirts', K(['hosthound'], 10, 'Kill 10 of the host around the Last Light', 'outskirts', 240), "Vhorun's host prowl the camp. Ten. I want people to sleep.", "Ten. Sleep, everyone. Mira's orders."],
    ['yt4', 'iven13', 34, 'Pilgrims\' Packs', 'ribs', I('pilgrimpack', 4, 'Gather 4 packs the pilgrims dropped on the way into the Throat'), "The pilgrims walked into his mouth. They dropped things. Bring me four packs. There'll be letters. Somebody should send them.", "Four letters home. I'll send them. 'Dear Mother, I've found a god. He's very big. Don't worry.' Oh."],
    ['yt5', 'nan14', 34, 'Hungering Fat', 'outskirts', C(['hungering'], 'Rendered Fat', 5, 'Bring Nan 5 measures of fat from the hungering'), "The hungering are fat. On what, I don't want to know. Five measures. For frying. Don't look at me like that."],
    ['yt6', 'cobb14', 34, 'Cobb\'s Hands', 'emberwatch', C(['gnawling', 'hosthound'], 'Soft Hide', 4, 'Bring Cobb 4 soft hides for ember-gloves'), "Gloves. For the ember. My hands have had enough. Four soft hides.", "Gloves! I'll never burn again. I'll burn again. But less."],
    ['yt7', 'mira13', 34, 'The Bites', 'plain', I('biteMark', 3, 'Mark 3 of the bites Vhorun took out of the Gnawed Plain'), "He chewed the plain on the way in. The bites are still there. Mark three on the map, so nobody walks into one in the dark."],
    ['yt8', 'iven13', 34, 'Gnawlings at the Watch', 'emberwatch', K(['gnawling', 'hungering'], 10, 'Clear 10 gnawlings and hungering around Ember Watch', 'emberwatch', 240), "The gnawlings come for the ember. They think it's food. Everything here thinks everything's food. Ten."],
    ['yt9', 'nan14', 34, 'Feed the Watch', 'emberwatch', A('emberwatch', 'Carry Nan\'s pot of stew to Ember Watch'), "Ember Watch hasn't had a hot meal in a week. Carry this. It's heavy. It's hot. Don't spill it. Don't eat it.", [["cobb14", "Stew! From Nan? Hot stew! Iven, wake up, there's stew!"]]],
    ['ytd1', 'nan14', 34, 'Pot Duty', 'outskirts', C(['gnawling', 'hungering'], 'Meat', 5, 'Bring Nan 5 cuts of meat for the pot'), "Five a day. The pot's always empty.", "Five. Same tomorrow.", { daily: true }],
  ]),
  ...side(T, LA, 'xt3', [
    ['yt10', 'ammara', 34, 'Starwright Lenses', 'ribs', I('starlens', 3, 'Find 3 lenses the Starwright watchers dropped among his ribs'), "The Starwrights drop their lenses sometimes. Find three on the ground. Don't take them off the watchers. They notice.", "Three. Look through one. He looks like a child. That's what they see. That's what they've always seen."],
    ['yt11', 'iven13', 34, 'Ser Halvane', 'plain', N('eatenknight13', 'Lay Ser Halvane, Half-Eaten, to rest on the Gnawed Plain'), "There's a knight on the plain who was half eaten and kept the other half. He's waiting for Vhorun to finish. Let him rest."],
    ['yt12', 'mira13', 34, 'The Gnawling King', 'plain', N('gnawking13', 'Kill the Gnawling King on the Gnawed Plain'), "The gnawlings have a king. Fat on crumbs of a god. Kill him and they'll scatter."],
    ['yt13', 'cobb14', 34, 'Empty-Eyed', 'ribs', K(['emptyeyed'], 10, 'Turn back 10 empty-eyed pilgrims walking into the Throat', 'ribs', 220), "The empty-eyed walk into him singing. Ten. Some of them will thank you. That's the worst part."],
    ['yt14', 'ammara', 34, 'Watchers', 'ribs', K(['starwatcher'], 8, 'Drive off 8 Starwright watchers among the ribs', 'ribs', 220), "The Starwrights watch. I want them to watch from further away. Eight."],
    ['yt15', 'nan14', 35, 'The Rib-Warden', 'ribs', N('ribwarden13', 'Kill the Rib-Warden among the Ribs of the World'), "Something guards his ribs. Every cook in camp wants it dead. It ate our wagon. Our cook-wagon. With the good pans."],
    ['yt16', 'iven13', 35, 'Greedmaw\'s Teeth', 'plain', C(['gnawling', 'hungering'], 'Greedy Tooth', 6, 'Collect 6 greedy teeth from the gnawlings and hungering'), "The things here grow teeth from eating his crumbs. Bad teeth. Six. I want to know what he's making them into."],
    ['yt17', 'cobb14', 35, 'Ember Road', 'emberwatch', I('embershrine', 1, 'Light the last ember-shrine on the road'), "One more shrine. The one by the Watch gate. I've saved it. For you. Light it."],
    ['yt18', 'mira13', 35, 'Voidspawn', 'outskirts', K(['voidspawn'], 10, 'Kill 10 voidspawn near the Last Light', 'outskirts', 260), "The voidspawn come up out of his shadow. Silent. Ten. Before they get into the camp."],
    ['yt19', 'iven13', 35, 'Bites, Again', 'plain', I('biteMark', 2, 'Mark 2 more fresh bites on the plain'), "He's still biting. Even lying down. Two new bites, the scouts say. Mark them."],
    ['ytd2', 'cobb14', 34, 'Ember Watch', 'emberwatch', K(['gnawling', 'hungering', 'hosthound'], 8, 'Guard Ember Watch against 8 things', 'emberwatch', 240), "Eight. Every day. The ember can't defend itself.", "Guarded. Same tomorrow.", { daily: true }],
  ]),
  ...side(T, LA, 'xt5', [
    ['yt20', 'ammara', 35, 'Ossiel', 'ribs', N('starherald13', 'Face Ossiel, Herald of the Starwrights, among the Ribs'), "Ossiel speaks for the Starwrights. Go and listen to him. Then stop him. In that order."],
    ['yt21', 'mira13', 35, 'The Last Pilgrim', 'lastpilgrim', A('lastpilgrim', 'Visit the statue of the Last Pilgrim in the south-west'), "There's a statue in the south-west. The Last Pilgrim. Somebody carved it the day he lay down. Go and see it. I can't. I knew her."],
    ['yt22', 'nan14', 35, 'The Pilgrim Queen', 'ribs', N('pilgrimqueen13', 'Find the Pilgrim Queen, leading the empty-eyed'), "The pilgrims have a queen. She feeds them to him. She ate my stew once and said it was 'adequate'. Find her."],
    ['yt22b', 'cobb14', 35, 'The Swallowed Light', 'heartless', A('heartless', 'Go to the crack in his side and look down at the Heartless Deep'), "Iven says his temple's flame is down there. In his belly. Go and look down the crack. Tell me if you see it. Blue. You'll know it."],
    ['yt23', 'iven13', 35, 'Host at the Throat', 'throatgate', K(['hosthound', 'voidspawn', 'hungering', 'emptyeyed'], 12, 'Clear 12 things at the gate of the Throat', 'throatgate', 240), "When we go down the Throat, the gate behind us has to be clear. Twelve."],
    ['yt24', 'mira13', 35, 'Lanterns for the Throat', 'throatgate', C(['hosthound', 'emptyeyed'], 'Stolen Lantern', 6, 'Take back 6 lanterns the host stole from the camps'), "The host steal lanterns. Take six back. Everybody's bringing a lantern to the Throat. I want them all to have one."],
    ['yt25', 'nan14', 35, 'One Last Stew', 'lastlight', TK('Eat with Nan before the Throat'), "Sit. Eat. Before you go down. Everyone eats before a battle. That's my rule. I made it up."],
    ['yt26', 'ammara', 35, 'Through the Lens', 'ribs', I('starlens', 1, 'Find the last Starwright lens among the ribs'), "One more lens. The big one. Find it. I want to look at him the way they look at him. Once."],
    ['yt27', 'cobb14', 35, 'Twelve Burns', 'emberwatch', TK('Talk to Brother Cobb'), "Twelve. I've burned my hands twelve times. This last one I did on purpose. To see if I'd flinch. I didn't."],
    ['yt28', 'iven13', 35, 'Pilgrims\' Letters', 'ribs', I('pilgrimpack', 2, 'Find 2 more pilgrims\' packs with letters home'), "Two more packs, the scouts say. With letters. Bring them. I'll send them. Every one."],
    ['yt29', 'mira13', 35, 'The Rib-Choir\'s Song', 'ribs', K(['emptyeyed', 'starwatcher'], 12, 'Silence 12 of the singers in his ribs', 'ribs', 220), "The pilgrims in his ribs sing him to sleep. Twelve fewer voices. I want him awake for this."],
    ['yt30', 'nan14', 35, 'The Gullet Road', 'heartless', K(['hungering', 'gnawling', 'voidspawn'], 12, 'Clear 12 things on the road to the Heartless Deep', 'heartless', 240), "The road to the crack in his side is full. Twelve. I've got a pot to send down with the raid. Don't ask."],
    ['yt31', 'iven13', 35, 'The Blue Flame', 'lastlight', TK('Sit with Iven and look at the blue light'), "Sit with me. Look up. The blue one. My temple's flame. Six hundred years. Just look at it with me. Just for a minute."],
    ['yt32', 'cobb14', 35, 'Ember for the Raid', 'throatgate', A('throatgate', 'Carry a coal from the ember to the Throat gate'), "A coal from the ember. Carry it to the gate. When the raid goes down, they'll light their lanterns from it. From us."],
    ['ytd3', 'mira13', 35, 'Throat Watch', 'throatgate', K(['hosthound', 'voidspawn', 'emptyeyed'], 8, 'Watch the Throat gate and clear 8 things', 'throatgate', 240), "Eight. Every day. Until he's dead.", "Clear. Same tomorrow.", { daily: true }],
  ]),
];
const DONE_T = { yt5: "Five. Fried gnawling tonight. Don't tell the pilgrims. They think they're holy.", yt7: "Three marked. One of them's still chewing. I heard it. I'm going to pretend I didn't.", yt8: "Ten. The ember's safe. The ember's always safe. I'd die first. Iven would die first. Cobb would die first. We've discussed it.", yt11: "Resting. Both halves. Together. He'd like that.", yt12: "The king's dead. The gnawlings are running in circles. Like a party with no host.", yt13: "Ten. Three of them said thank you. I said you're welcome. I don't know what I meant.", yt14: "Further away. They're still watching. They're always watching. At least now they have to squint.", yt15: "Dead? The pans? Did you see the pans? Never mind. I'll make do. I always make do.", yt16: "Teeth inside teeth. He's making them into him. Little hungry copies. We need to finish this.", yt17: [["cobb14", "There. The whole road's lit, from the Light to the Watch."], ["iven13", "Look at it from the wall, Cobb. Look. It's a string of little suns."]], yt18: "Ten. Silent. Gone. The camp's breathing easy. Well. Easier.", yt19: "Two more. He's still hungry. Lying down, half-dead, still hungry. That's what we're up against.", yt20: "'A family matter.' He said it to you too? They always say that. Every time.", yt21: "She was a baker. In Corrandel. She walked here to see if he'd like her bread. He ate the bread. Then he ate her. That statue's all that's left.", yt22: "Adequate. ADEQUATE. Is she dead? Good. My stew is excellent.", yt22b: "Blue? You saw blue? It's still there. It's still lit. Down in the dark, in his belly, still lit. Six hundred years.", yt23: "Clear. The gate's ours. Behind us, at least. Ahead's his.", yt24: "Six. Everyone's got a lantern now. Every single one. Look at the camp. It looks like the sky.", yt25: "There. Full? Good. Now go. Come back hungry. That's an order. That's my only order.", yt26: "Through this one he's small. Curled up. Like a child asleep. They made him. They'll mourn him. I won't.", yt27: "Twelve burns, and I'd do it twelve more times. Don't tell Iven I said that. He'd make me.", yt28: "Two more. 'Dear Mother, I'm almost there.' 'Dear Pell, look after the goat.' I'll send them. I'll send all of them.", yt29: "Twelve. He's stirring. Good. I want him awake. I want him to see us coming.", yt30: "Twelve. The pot goes down tomorrow. With a raid. Stew for the heroes. Don't make that face.", yt31: "Thank you. It's still there. I'll see it go home. Whatever happens, I'll see it go home.", yt32: "There. The ember's at the gate. Every lantern that goes down the Throat will be lit from us." };
for (const q of yt) if (DONE_T[q.id]) q.done = [].concat(typeof DONE_T[q.id] === 'string' ? [DONE_T[q.id]] : DONE_T[q.id]);

// ---------- a fourth handful in each land ----------
const yw2 = side(W, LA, 'xw2', [
  ['yw37', 'tobin14', 31, 'Crawlers in the Post', 'lampfall', K(['woundcrawler'], 8, 'Clear 8 wound-crawlers out of the Compact post-bags', 'lampfall', 700), "Something's crawling in the post-bags. Wound-crawlers. They eat paper. They ate a love letter. It was mine. Eight.", "Eight. I'll write the letter again. It'll be worse. They always are, the second time."],
  ['yw38', 'gret14', 31, 'Hollow Hound Collars', 'woundedge', C(['hollowhound'], 'Iron Collar', 5, 'Take 5 iron collars from the hollow hounds'), "The hounds wear collars. Iron. Somebody's dogs, once. Five. I'll make horseshoes. The horses won't mind.", "Five. Horseshoes by tonight. Somebody's dogs. Somebody's horses now. That's how it goes."],
  ['yw39', 'oswin13', 31, 'Lantern Watch', 'lampfall', TK('Stand the lantern watch with Captain Oswin'), "The camp keeps one lantern lit all night. Somebody has to watch it. Tonight it's us. Bring your own boredom.", "Dawn. Nothing happened. That's the best night I've had in a month. Thank you for nothing happening."],
  ['yw40', 'varga13', 31, 'Wraith-Hunting', 'ironrim', K(['rockwraith'], 10, 'Break 10 rock-wraiths around the Iron Rim', 'ironrim', 240), "Rock-wraiths come out of the cliff at night and pull my sentries in. Ten.", "Ten. The cliff's quiet. Cliffs should be quiet. That's their whole job."],
  ['yw41', 'sela13', 31, 'Unblinking', 'woundedge', A('woundedge', 'Stand at the Wound\'s edge and watch it until something moves'), "Stand at the edge. Watch. Don't blink. Tell me what moves. Something always moves.", "Lights? Deep down? Going further down? He's still going. All the way down. I knew it."],
  ['yw42', 'gret14', 32, 'Varga\'s Sword', 'ironrim', C(['hollowwarden'], 'Warden Steel', 3, 'Bring Gret 3 lengths of warden steel for Varga\'s new sword'), "Varga broke her sword on a voidspawn. Again. Three lengths of warden steel and I'll make her one she can't break. She'll try.", "There. A sword. She'll break it. She'll break it on something very big. I'll be proud."],
  ['yw43', 'tobin14', 32, 'Gloom in the Halls', 'halls', K(['gloomcaster', 'hollowwarden'], 10, 'Clear 10 things from the Halls road so the post can get through', 'halls', 240), "The post goes past the Halls. Or it did. Ten, and it can again.", "Ten. The post's through. Somebody got a letter today. They cried. Good crying."],
  ['yw44', 'oswin13', 32, 'Upcallers', 'ironrim', K(['upcaller'], 8, 'Silence 8 Upward Choir lamp-eaters', 'ironrim', 700), "The Choir's lamp-eaters swallow our light and sing about it. Eight.", "Eight. The camp lamps stay lit. Nobody sings. I like it that way."],
  ['yw45', 'sela13', 32, 'Dark Things in the Pit', 'pit', K(['lightless', 'voidspawn'], 10, 'Clear 10 things climbing out of the Weeping Pit', 'pit', 240), "Things climb out of the Pit at night. I count them. Ten tonight. Make it none.", "None. I counted. Not one. I'm going to count again, to be sure."],
  ['yw46', 'tobin14', 32, 'Tobin\'s Last Run', 'lampfall', TK('Hear Tobin\'s news'), "I've been made a captain. Of runners. Me. I have to stop running and tell other people to run. I don't know how to stop.", "You'll still race me? Once a week? Good. Good. Captains can race. I'll make it a rule."],
]);
const ym2 = side(M, CF, 'xm2', [
  ['ym34', 'tom14', 31, 'A Candle for Everyone', 'candlehold', TK('Help Wick-Tom give out candles at the gate'), "Stand at the gate with me. Everyone who comes in gets a candle. Free. Don't tell anyone it's free.", "Forty candles. Forty people. They'll come back for more. That's the trade. You've seen it now."],
  ['ym35', 'bram14', 31, 'Moths in the Belfry', 'lasthearth', K(['candlemoth'], 10, 'Clear 10 gloom-moths out of Last Hearth\'s belfry', 'lasthearth', 700), "The moths nest in the belfry. Every time I ring, they come down like snow. Ten.", "Ten. I rang it. Nothing came down but sound. Lovely sound."],
  ['ym36', 'nell13', 31, 'Wax and Wick', 'candleroad', C(['candlemoth', 'gloomstalker'], 'Tallow', 6, 'Bring Nell 6 lumps of tallow'), "Six lumps of tallow. Candlehold goes through candles like the dark goes through people.", "Six. A hundred candles. Somebody give me a hundred more hands."],
  ['ym37', 'aldous13', 32, 'The Wall', 'candlehold', K(['gloomstalker', 'lightless'], 10, 'Clear 10 things from under Candlehold\'s walls', 'candlehold', 200), "They come right up to the walls now. Ten. I want them a long way from the walls.", "Ten. They'll stay back for a day or two. Long enough to rebuild the gate. Again."],
  ['ym38', 'mourne13', 32, 'Mourne\'s Confession', 'lasthearth', TK('Listen to Sister Mourne'), "I was a Sister of the Long Dusk. For ten years. I put out candles for a living. I'd like to say that out loud to somebody who won't forgive me.", "There. Said. You didn't forgive me. Good. I don't want it yet. I want to earn it."],
  ['ym39', 'tom14', 32, 'Window Thieves', 'avenmoor', K(['lightless', 'dusksister'], 10, 'Clear 10 of the things snuffing candles in Avenmoor\'s windows', 'avenmoor', 220), "Somebody puts candles in Avenmoor's windows. Me. Somebody else puts them out. Ten.", "Ten. The candles are staying lit tonight. I'll walk past and count them. I like counting candles."],
  ['ym40', 'bram14', 32, 'Bell Rope', 'avenmoor', C(['lightlessknight'], 'Knight\'s Cord', 4, 'Take 4 knights\' cords to make a new bell rope'), "My bell rope's frayed. Avenmoor's knights wore good cord. Four. They won't mind. They'd want the bell rung.", "New rope. I rang it. Heavier. Better. It sounds like the knights."],
  ['ym41', 'nell13', 32, 'Starless Wood Wax', 'wood', K(['candlemoth', 'shadowtreant'], 10, 'Clear 10 things in the Starless Wood so Nell\'s gatherers can work', 'wood', 220), "My gatherers go into the Wood for bark-wax. They come back fewer. Ten.", "Ten. They all came back today. All of them. I counted twice."],
  ['ym42', 'aldous13', 33, 'Avenmoor\'s Banner', 'avenmoor', A('avenmoor', 'Raise Candlehold\'s banner over the ruins of Avenmoor'), "Take this banner. Climb what's left of the town hall. Raise it. Avenmoor will know someone's coming back.", "Raised. I saw it from the wall. A little flag on a big ruin. It's the best thing I've seen in a year."],
  ['ym43', 'mourne13', 33, 'Sisters\' Lamps', 'court', C(['dusksister'], 'Snuffed Lamp', 5, 'Take back 5 lamps the Sisters snuffed'), "The Sisters carry lamps they've put out. Trophies. Five. I'll relight them. One for each year I helped.", "Five. Lit. Five years. Five more to go. I'll find them."],
  ['ym44', 'tom14', 33, 'The Last Candle', 'candlehold', TK('Watch Wick-Tom make his last candle'), "I'm making my last candle. My hands shake too much now. Watch. Somebody should see the last one.", "There. The last one. It's crooked. Give it to Nell. She'll know what to do with it. She'll light it."],
  ['ym45', 'bram14', 33, 'Gloomcasters at the Gate', 'gate', K(['gloomcaster', 'voidspawn'], 10, 'Clear 10 gloomcasters and voidspawn from the old south gate', 'gate', 240), "The gate where the bells used to warn of wolves. Gloomcasters now. Ten.", "Ten. I'll put a bell on that gate. A small one. For old times."],
  ['ym46', 'nell13', 33, 'Candles for the Dead', 'avenmoor', TK('Light candles for Avenmoor\'s dead with Nell'), "One candle for every house in Avenmoor. I made them all. Help me light them. It'll take a while. There were a lot of houses.", "All lit. You can see Avenmoor from Candlehold now. Every window. Like it's still there."],
]);
const yf2 = side(F, TH, 'xf2', [
  ['yf34', 'inga14', 32, 'Wisp-Light', 'thaw', C(['icewisp'], 'Cold Light', 5, 'Catch 5 cold lights from the ice-wisps'), "Wisp-light doesn't melt the snow. Good for lanterns in the ice-houses. Five.", "Five. The ice-houses have light now. Cold light. The children think it's magic. It is."],
  ['yf35', 'jory14', 32, 'Frost-Wights', 'hearthsend', K(['frostwight'], 10, 'Lay 10 frost-wights to rest near Hearth\'s End', 'hearthsend', 700), "The frost-wights were prisoners. From the cells. They walked out and froze. Ten. Let them rest.", "Ten. I knew a few of them. Not well. Well enough. They're resting now."],
  ['yf36', 'astrid13', 32, 'Thawborn Spears', 'thaw', C(['snowstalker', 'glacialhulk'], 'Long Bone', 6, 'Bring Astrid 6 long bones for spear shafts'), "The Thawborn carry spears. Bone shafts. Six long bones. From things that tried to eat us.", "Six. Spears from the things that hunted us. The north is very fond of that kind of joke."],
  ['yf37', 'hallvard13', 32, 'Runner\'s Rest', 'hearthsend', TK('Sit with Hallvard by the fire'), "Sit by the fire. I've run a hundred miles this week. I want to sit with someone who's done the same. You look like you have.", "That's it. Just the fire. Nobody says anything. That's the best bit of running. The stopping."],
  ['yf38', 'inga14', 33, 'Hulks on the Road', 'titheroad', K(['glacialhulk'], 8, 'Bring down 8 glacial hulks blocking the Tithe Road', 'titheroad', 240), "The hulks sit on the road and pretend to be snowdrifts. Then they eat the wagons. Eight.", "Eight. The drifts are just drifts now. Mostly. Kick them first."],
  ['yf39', 'jory14', 33, 'Wagon Goods', 'titheroad', I('frozenwagon', 1, 'Search the last frozen wagon on the Tithe Road'), "One more wagon. The last one. It's got my family's mark on the side. I can't look. You look.", "My mother's quilt. It's my mother's quilt. Frozen solid. I'll thaw it. I'll thaw it slowly."],
  ['yf40', 'astrid13', 33, 'Tithe-Takers', 'titheroad', K(['tithetaker'], 10, 'Break 10 tithe-takers still collecting on the road', 'titheroad', 240), "They're still collecting. From nobody. Ten.", "Ten. The road's free. Free road. Free north."],
  ['yf41', 'hallvard13', 33, 'Glacier Run', 'glacier', A('glacier', 'Run to the middle of the Glass Glacier and back'), "Run to the middle of the Glacier and back. Runners have to know the ice. You'll want to know it too.", "Back? Fast. You slid the last bit. I saw. Everyone slides the last bit."],
  ['yf42', 'inga14', 33, 'Rimeguard Banners', 'glacier', C(['rimeguard'], 'Frost Banner', 4, 'Take 4 banners from the Rimeguard'), "The Rimeguard carry the King's banners. Four. We'll burn them in the square. Everybody likes a fire. Even me."],
  ['yf43', 'jory14', 34, 'The Turnkey\'s Keys', 'cells', C(['rimeguard', 'frostwight'], 'Cell Key', 5, 'Find 5 keys to the Tithe-Cells'), "Five keys. The cells' keys. I want them. I want to throw them in the sea. I've never seen the sea."],
  ['yf44', 'hallvard13', 34, 'Runners for the Post', 'thawhold', TK('Help Hallvard choose his first runners'), "I've got twenty who want to run the post. I need six. Help me choose. Pick the ones who look like they'll keep going."],
  ['yf45', 'astrid13', 34, 'The Thawborn Feast', 'thawhold', TK('Sit at the Thawborn feast'), "The Thawborn are having a feast. First since the thaw. Sit at my table. Eat the fish. Don't eat the other fish."],
  ['yf46', 'inga14', 34, 'Warm Hands', 'thawhold', C(['snowstalker'], 'Stalker Pelt', 4, 'Bring Inga 4 pelts for mittens'), "I want mittens. Don't laugh. Four pelts. My hands get cold now. Since the Heart broke. I've been cold ever since. It's wonderful."],
]);
const yt2 = side(T, LA, 'xt2', [
  ['yt33', 'nan14', 34, 'Firewood', 'outskirts', C(['hosthound', 'gnawling'], 'Dry Bone', 6, 'Bring Nan 6 dry bones for the cook-fire'), "No trees here. He ate them. Dry bones burn. Six.", "Six. The pot's boiling. Don't think about the fire. Think about the stew."],
  ['yt34', 'cobb14', 34, 'Hands Off the Ember', 'emberwatch', K(['gnawling'], 10, 'Chase 10 gnawlings away from Ember Watch', 'emberwatch', 240), "The gnawlings try to eat the ember. Every night. Ten.", "Ten. The ember's fine. The ember's always fine. My hands are fine too, today."],
  ['yt35', 'mira13', 34, 'Every Lantern', 'lastlight', TK('Help Mira count the lanterns in the camp'), "Count them with me. Every lantern in the Last Light. I want to know how many of us there are.", "Four hundred and twelve. Four hundred and twelve lanterns. That's a good number. I don't know why. It feels like a good number."],
  ['yt36', 'iven13', 34, 'The Hungering', 'plain', K(['hungering'], 10, 'Kill 10 of the hungering on the Gnawed Plain', 'plain', 240), "The hungering are the worst of his crumbs. Ten.", "Ten. They didn't stop eating even while they died. That's him. That's what he's made."],
  ['yt37', 'ammara', 34, 'What Ammara Ran From', 'lastlight', TK('Ask Ammara about the Starwrights'), "You want to know why I ran. Sit. It's not a long story. It's a tall one.", "They asked everyone's name. In the Empress's court. They wrote them down. I didn't want my name in their book. So I ran. I'm still running. I'm just running toward them now."],
  ['yt38', 'nan14', 35, 'Stew for the Ribs', 'ribs', A('ribs', 'Carry Nan\'s stew to the scouts at the Ribs'), "The scouts at the Ribs haven't eaten in two days. Take this. It's hot. It's heavy. It's stew.", "Delivered? They ate it all? Standing up? Good. That's the highest compliment a cook gets."],
  ['yt39', 'cobb14', 35, 'Pilgrim Prayers', 'ribs', C(['emptyeyed'], 'Prayer Card', 5, 'Take 5 prayer cards from the empty-eyed pilgrims'), "The empty-eyed carry prayer cards. To him. Five. I want to read what they say. I want to know what they think he'll give them."],
  ['yt40', 'mira13', 35, 'Host on the Road', 'outskirts', K(['hosthound', 'voidspawn'], 12, 'Clear 12 of the host from the road into camp', 'outskirts', 260), "The road into camp. Twelve. Everybody's coming to the Last Light now. I want them to get here.", "Twelve. They're coming in. The Compact. The Legion. The Candlehold Free. I can see their lanterns on the road."],
  ['yt41', 'iven13', 35, 'Iven\'s Temple', 'emberwatch', TK('Hear Iven talk about his temple'), "Six hundred years. My temple kept a flame lit for six hundred years. Sit. I'll tell you about the people who kept it.", "Every one of them, by name. I know them all. Somebody has to. When the flame comes home, I'll tell it."],
  ['yt42', 'nan14', 35, 'The Gnawling King\'s Crown', 'plain', C(['gnawling'], 'Shiny Thing', 4, 'Take 4 shiny things the gnawlings have been hoarding'), "Gnawlings hoard shiny things. Spoons. Rings. My ladle. MY LADLE. Four shiny things. One of them had better be my ladle."],
  ['yt43', 'ammara', 35, 'Starwright Lenses', 'ribs', C(['starwatcher'], 'Lens', 3, 'Take 3 lenses from the Starwright watchers'), "I said not to take them off the watchers. Now I'm saying take three. Things change. They're watching too closely."],
  ['yt44', 'cobb14', 35, 'One More Burn', 'emberwatch', TK('Watch Brother Cobb carry the ember'), "Watch me carry it. To the Throat gate and back. Bare hands. I want somebody to see. I don't know why."],
]);
const MORE_DONE = { yf42: "Burned. In the square. Everybody stood round it. Even me. Warm hands, warm face. I could get used to this.", yf43: "Five keys. I'm going to walk to the sea. However far it is. And throw them in. Then I'm going to walk back.", yf44: "Six. Good choices. They'll keep going. The north will have a post. Hallvard's Post. I like the sound of it.", yf45: "You ate the other fish. I said don't eat the other fish. ...How was it? Don't answer.", yf46: "Mittens. MITTENS. Don't laugh. I'm wearing them. I'm never taking them off.", yt39: "'Make me full.' 'Make me never hungry again.' 'Take me inside you where it's warm.' They think he's a hearth. He's a mouth.", yt42: "My ladle! You found my ladle! I'll make the best stew of my life tonight. Possibly ever.", yt43: "Three. They'll be blind for a bit. They'll be angry. Starwrights get angry very quietly.", yt44: "Thirteen. That's thirteen burns. Worth it. Every one. Don't tell Iven." };
const ym2b = ym2;
for (const q of [...yw2, ...ym2b, ...yf2, ...yt2]) if (MORE_DONE[q.id]) q.done = [MORE_DONE[q.id]];
QUESTS.push(...finish35([...yw, ...ym, ...yf, ...yt, ...yw2, ...ym2b, ...yf2, ...yt2]));
